CREATE OR REPLACE FUNCTION ECAMS.HOLIDAYCHECK

RETURN VARCHAR2
-- 0: 처리될 되상 1:스킵

IS
  ACPTDATE  VARCHAR2(12);
  VCNT      INTEGER := 0;
  CONFTIME  VARCHAR2(12);
BEGIN
    SELECT COUNT(*)
      INTO VCNT
      FROM CMM0050
     WHERE CM_HOLIDAY=TO_CHAR(SYSDATE,'YYYYMMDD')
       AND CM_CLOSEDT IS NULL;
    IF VCNT > 0 THEN
       RETURN 'OK';
    END IF;

    IF TO_CHAR(SYSDATE,'d') = '7' OR TO_CHAR(SYSDATE,'d') = '1' THEN
       RETURN 'OK';
    END IF;

    SELECT COUNT(*)
      INTO VCNT
      FROM CMM0014
     WHERE decode(to_char(SYSDATE,'d'),1,'03',6,'02',7,'03','01') = cm_timecd
       AND CM_STTIME<=TO_CHAR(SYSDATE,'HH24MI')
       AND CM_EDTIME>=TO_CHAR(SYSDATE,'HH24MI');
    IF VCNT = 0 THEN
       RETURN 'OK';
    END IF;
    return 'NO';
end;